#include "pfs/client.hpp"
#include "pfs/util.hpp"
#include <future>
#include <stdexcept>

namespace pfs { namespace pv=pfs::v1;
static void check(const grpc::Status&s){if(!s.ok())throw std::runtime_error(s.error_message());}
Client::Client(std::string addr,std::string id):coordinator_(pv::Coordinator::NewStub(grpc::CreateChannel(addr,grpc::InsecureChannelCredentials()))),id_(id.empty()?uuid():std::move(id)){}
Client::Token Client::acquire(const std::string&f,pv::TokenMode mode){pv::AcquireTokenRequest r;r.set_file(f);r.set_client_id(id_);r.set_mode(mode);r.set_timeout_ms(30000);r.set_lease_ms(120000);pv::AcquireTokenResponse o;grpc::ClientContext c;check(coordinator_->AcquireToken(&c,r,&o));return{f,o.token()};}
void Client::release(const Token&t)noexcept{pv::ReleaseTokenRequest r;r.set_file(t.file);r.set_token(t.value);pv::Empty o;grpc::ClientContext c;coordinator_->ReleaseToken(&c,r,&o);}
void Client::write(const std::string&name,const std::string&data,uint32_t stripe){auto t=acquire(name,pv::TOKEN_MODE_WRITE);try{pv::ReserveWriteRequest r;r.set_name(name);r.set_size(data.size());r.set_stripe_size(stripe);r.set_token(t.value);pv::FileLayout l;grpc::ClientContext c;check(coordinator_->ReserveWrite(&c,r,&l));std::vector<std::future<std::string>>fs;for(auto&s:l.stripes()){auto chunk=data.substr(uint64_t(s.index())*stripe,s.size());fs.push_back(std::async(std::launch::async,[s,l,chunk]{auto stub=pv::Storage::NewStub(grpc::CreateChannel(s.node_address(),grpc::InsecureChannelCredentials()));pv::PutStripeRequest q;q.set_file(l.name());q.set_version(l.version());q.set_index(s.index());q.set_data(chunk);pv::PutStripeResponse o;grpc::ClientContext c;check(stub->PutStripe(&c,q,&o));if(o.checksum()!=checksum(chunk))throw std::runtime_error("stripe checksum mismatch");return o.checksum();}));}for(int i=0;i<l.stripes_size();++i)l.mutable_stripes(i)->set_checksum(fs[i].get());pv::CommitWriteRequest cr;*cr.mutable_layout()=l;cr.set_token(t.value);pv::Empty out;grpc::ClientContext cc;check(coordinator_->CommitWrite(&cc,cr,&out));release(t);}catch(...){release(t);throw;}}
std::string Client::read(const std::string&name){auto t=acquire(name,pv::TOKEN_MODE_READ);try{pv::GetLayoutRequest r;r.set_name(name);r.set_token(t.value);pv::FileLayout l;grpc::ClientContext c;check(coordinator_->GetLayout(&c,r,&l));std::vector<std::future<std::string>>fs;for(auto&s:l.stripes())fs.push_back(std::async(std::launch::async,[s,l]{auto stub=pv::Storage::NewStub(grpc::CreateChannel(s.node_address(),grpc::InsecureChannelCredentials()));pv::GetStripeRequest q;q.set_file(l.name());q.set_version(l.version());q.set_index(s.index());pv::GetStripeResponse o;grpc::ClientContext c;check(stub->GetStripe(&c,q,&o));if(o.checksum()!=s.checksum()||checksum(o.data())!=s.checksum())throw std::runtime_error("stripe checksum mismatch");return o.data();}));std::string out;out.reserve(l.size());for(auto&f:fs)out+=f.get();out.resize(l.size());release(t);return out;}catch(...){release(t);throw;}}
void Client::remove(const std::string&name){auto t=acquire(name,pv::TOKEN_MODE_WRITE);try{pv::DeleteFileRequest r;r.set_name(name);r.set_token(t.value);pv::FileLayout l;grpc::ClientContext c;check(coordinator_->DeleteFile(&c,r,&l));for(auto&s:l.stripes()){auto stub=pv::Storage::NewStub(grpc::CreateChannel(s.node_address(),grpc::InsecureChannelCredentials()));pv::DeleteStripeRequest q;q.set_file(name);q.set_version(l.version());q.set_index(s.index());pv::Empty o;grpc::ClientContext cc;stub->DeleteStripe(&cc,q,&o);}release(t);}catch(...){release(t);throw;}}
std::vector<pv::FileInfo>Client::list(){pv::Empty r;pv::ListFilesResponse o;grpc::ClientContext c;check(coordinator_->ListFiles(&c,r,&o));return{o.files().begin(),o.files().end()};}
}
